/**
 * Codec2 WASM loader (docs/design/media-tiers.md §3).
 *
 * The artifact is generated by `scripts/build-voice-wasm.sh` into
 * `public/voice/openmesh_voice.wasm` (gitignored). CI builds it before pnpm build;
 * local builds may not have it, so every entry point degrades gracefully.
 *
 * C ABI (frozen):
 *   uint8_t* om_voice_encode(uint32_t tier, const uint8_t* pcm, uint32_t len, uint32_t* out_len);
 *   uint8_t* om_voice_decode(uint32_t tier, const uint8_t* payload, uint32_t len, uint32_t* out_len);
 *   void     om_voice_free(uint8_t* ptr, uint32_t len);
 *   uint32_t om_voice_frame_bytes(uint32_t tier);
 */
import type { VoiceTierId } from '../lib/media-tiers';
import { codec2TierIndex } from '../lib/media-tiers';

export class Codec2UnavailableError extends Error {
  readonly reason: 'missing' | 'invalid' | 'fetch' | 'memory';
  constructor(message: string, reason: 'missing' | 'invalid' | 'fetch' | 'memory' = 'missing') {
    super(message);
    this.name = 'Codec2UnavailableError';
    this.reason = reason;
  }
}

interface Codec2Exports {
  memory: WebAssembly.Memory;
  om_voice_encode?: (tier: number, pcmPtr: number, len: number, outLenPtr: number) => number;
  om_voice_decode?: (tier: number, payloadPtr: number, len: number, outLenPtr: number) => number;
  om_voice_free?: (ptr: number, len: number) => void;
  om_voice_frame_bytes?: (tier: number) => number;
  /** Optional allocator; the frozen ABI does not list it, but a small shim may export it. */
  om_voice_alloc?: (size: number) => number;
  om_voice_dealloc?: (ptr: number) => void;
}

export interface Codec2Instance {
  encode(pcm: Int16Array, tier: VoiceTierId): Uint8Array;
  decode(payload: Uint8Array, tier: VoiceTierId): Int16Array;
  frameBytes(tier: VoiceTierId): number;
}

export function codec2WasmUrl(): string {
  const base = import.meta.env.BASE_URL || '/';
  const relative = `${base}voice/openmesh_voice.wasm`;
  if (typeof document !== 'undefined' && document.baseURI) {
    try {
      return new URL(relative, document.baseURI).toString();
    } catch {
      return relative;
    }
  }
  return relative;
}

let loadPromise: Promise<Codec2Instance> | null = null;
let availability: 'unknown' | 'available' | 'unavailable' = 'unknown';
let availabilityMessage: string | null = null;

function wrapExports(exports: WebAssembly.Exports): Codec2Instance {
  const raw = exports as unknown as Codec2Exports;
  if (!(raw.memory instanceof WebAssembly.Memory)) {
    throw new Codec2UnavailableError('The voice WASM does not export a memory.', 'invalid');
  }
  if (
    typeof raw.om_voice_encode !== 'function' ||
    typeof raw.om_voice_decode !== 'function' ||
    typeof raw.om_voice_free !== 'function' ||
    typeof raw.om_voice_frame_bytes !== 'function'
  ) {
    throw new Codec2UnavailableError('The voice WASM is missing the frozen Codec2 C ABI.', 'invalid');
  }
  const memory = raw.memory;
  let scratchOffset = memory.buffer.byteLength;
  const scratchAlloc = (size: number): number => {
    const needed = Math.max(1, size);
    const pages = Math.ceil((scratchOffset + needed + 64) / 65536);
    if (pages > memory.buffer.byteLength / 65536) {
      try {
        memory.grow(pages - memory.buffer.byteLength / 65536);
      } catch {
        throw new Codec2UnavailableError('The voice WASM is out of memory.', 'memory');
      }
    }
    const ptr = scratchOffset;
    scratchOffset += needed + 8;
    return ptr;
  };
  const alloc = (size: number): number => {
    if (typeof raw.om_voice_alloc === 'function') {
      const ptr = raw.om_voice_alloc(size);
      if (!ptr) throw new Codec2UnavailableError('The voice WASM could not allocate memory.', 'memory');
      return ptr;
    }
    return scratchAlloc(size);
  };
  const release = (ptr: number): void => {
    if (typeof raw.om_voice_alloc === 'function' && typeof raw.om_voice_dealloc === 'function') {
      raw.om_voice_dealloc(ptr);
    }
  };
  const outLenPtrHolder = { ptr: 0 };
  const outLenPtr = (): number => {
    if (!outLenPtrHolder.ptr) outLenPtrHolder.ptr = alloc(4);
    return outLenPtrHolder.ptr;
  };
  const readOut = (ptr: number, len: number): Uint8Array => {
    if (!ptr || len <= 0) return new Uint8Array(0);
    const copy = new Uint8Array(memory.buffer, ptr, len).slice();
    raw.om_voice_free?.(ptr, len);
    return copy;
  };
  return {
    encode(pcm, tier) {
      if (pcm.length === 0) return new Uint8Array(0);
      const tierIndex = codec2TierIndex(tier);
      const input = new Uint8Array(pcm.buffer, pcm.byteOffset, pcm.byteLength);
      const ptr = alloc(input.byteLength);
      new Uint8Array(memory.buffer, ptr, input.byteLength).set(input);
      const lenPtr = outLenPtr();
      new DataView(memory.buffer).setUint32(lenPtr, 0, true);
      const outPtr = raw.om_voice_encode!(tierIndex, ptr, input.byteLength, lenPtr);
      const outLen = new DataView(memory.buffer).getUint32(lenPtr, true);
      release(ptr);
      if (!outPtr || outLen === 0) throw new Codec2UnavailableError('Codec2 encoding failed.', 'invalid');
      return readOut(outPtr, outLen);
    },
    decode(payload, tier) {
      if (payload.length === 0) return new Int16Array(0);
      const tierIndex = codec2TierIndex(tier);
      const input = new Uint8Array(payload.buffer, payload.byteOffset, payload.byteLength);
      const ptr = alloc(input.byteLength);
      new Uint8Array(memory.buffer, ptr, input.byteLength).set(input);
      const lenPtr = outLenPtr();
      new DataView(memory.buffer).setUint32(lenPtr, 0, true);
      const outPtr = raw.om_voice_decode!(tierIndex, ptr, input.byteLength, lenPtr);
      const outLen = new DataView(memory.buffer).getUint32(lenPtr, true);
      release(ptr);
      if (!outPtr || outLen === 0) throw new Codec2UnavailableError('Codec2 decoding failed.', 'invalid');
      const bytes = readOut(outPtr, outLen);
      return new Int16Array(bytes.buffer, 0, Math.floor(bytes.byteLength / 2));
    },
    frameBytes(tier) {
      const bytes = raw.om_voice_frame_bytes!(codec2TierIndex(tier));
      return Number.isFinite(bytes) && bytes > 0 ? bytes : 0;
    },
  };
}

/** Instantiate the voice WASM once. Rejects with Codec2UnavailableError when absent. */
export async function loadCodec2(fetchImpl: typeof fetch = fetch): Promise<Codec2Instance> {
  if (loadPromise) return loadPromise;
  const url = codec2WasmUrl();
  loadPromise = (async () => {
    let buffer: ArrayBuffer;
    try {
      const response = await fetchImpl(url, { cache: 'no-store' });
      if (!response.ok) {
        throw new Codec2UnavailableError(
          response.status === 404
            ? 'Codec2 voice is unavailable: this build does not include voice/openmesh_voice.wasm. High-quality Opus still works.'
            : `Codec2 voice could not be loaded (${response.status}). High-quality Opus still works.`,
          response.status === 404 ? 'missing' : 'fetch',
        );
      }
      buffer = await response.arrayBuffer();
    } catch (error) {
      if (error instanceof Codec2UnavailableError) throw error;
      throw new Codec2UnavailableError(
        'Codec2 voice is unavailable: the WASM file could not be fetched. High-quality Opus still works.',
        'fetch',
      );
    }
    if (!buffer.byteLength) {
      throw new Codec2UnavailableError('Codec2 voice is unavailable: the WASM file is empty.', 'missing');
    }
    try {
      const result = await WebAssembly.instantiate(buffer, {});
      return wrapExports(result.instance.exports);
    } catch (error) {
      if (error instanceof Codec2UnavailableError) throw error;
      throw new Codec2UnavailableError('Codec2 voice is unavailable: the WASM artifact is invalid.', 'invalid');
    }
  })();
  try {
    const instance = await loadPromise;
    availability = 'available';
    availabilityMessage = null;
    return instance;
  } catch (error) {
    loadPromise = null;
    availability = 'unavailable';
    availabilityMessage = error instanceof Error ? error.message : String(error);
    throw error;
  }
}

/** Cached availability probe for the recorder UI; never throws. */
export async function probeCodec2(): Promise<{ available: boolean; message: string | null }> {
  if (availability === 'available') return { available: true, message: null };
  if (availability === 'unavailable') return { available: false, message: availabilityMessage };
  try {
    await loadCodec2();
    return { available: true, message: null };
  } catch (error) {
    return { available: false, message: error instanceof Error ? error.message : String(error) };
  }
}

export function codec2AvailabilitySync(): 'unknown' | 'available' | 'unavailable' {
  return availability;
}

export async function encodePcmCodec2(pcm: Int16Array, tier: VoiceTierId): Promise<Uint8Array> {
  const instance = await loadCodec2();
  return instance.encode(pcm, tier);
}

export async function decodePcmCodec2(payload: Uint8Array, tier: VoiceTierId): Promise<Int16Array> {
  const instance = await loadCodec2();
  return instance.decode(payload, tier);
}

/** Test helper: forget the cached instance/probe (does not abort an in-flight load). */
export function resetCodec2CacheForTests(): void {
  loadPromise = null;
  availability = 'unknown';
  availabilityMessage = null;
}
